// House Music Drum Pattern Generator
const bpm = $input.first().json.bpm || 128;
const bars = $input.first().json.bars || 8;
const ticksPerBeat = 480;
const beatsPerBar = 4;

// MIDI note numbers for drum sounds
const drumNotes = {
  kick: 36,      // C1
  snare: 38,     // D1
  closedHat: 42, // F#1
  openHat: 46,   // A#1
  clap: 39,      // D#1
  rimshot: 37,   // C#1
  crash: 49      // C#2
};

const midiEvents = [];
let eventId = 0;

// Generate kick pattern (4 on the floor)
for (let bar = 0; bar < bars; bar++) {
  for (let beat = 0; beat < beatsPerBar; beat++) {
    const tick = (bar * beatsPerBar + beat) * ticksPerBeat;
    midiEvents.push({
      id: eventId++,
      type: 'noteOn',
      tick: tick,
      note: drumNotes.kick,
      velocity: beat === 0 ? 110 : 100, // Accent first beat
      channel: 9,
      duration: ticksPerBeat / 2
    });
  }
}

// Generate snare/clap pattern (beats 2 and 4)
for (let bar = 0; bar < bars; bar++) {
  [1, 3].forEach(beat => {
    const tick = (bar * beatsPerBar + beat) * ticksPerBeat;

    // Alternate between snare and clap for variation
    const useClap = bar % 2 === 1;

    midiEvents.push({
      id: eventId++,
      type: 'noteOn',
      tick: tick,
      note: useClap ? drumNotes.clap : drumNotes.snare,
      velocity: 105,
      channel: 9,
      duration: ticksPerBeat / 2
    });
  });
}

// Generate hi-hat pattern (8th notes)
for (let bar = 0; bar < bars; bar++) {
  for (let eighth = 0; eighth < beatsPerBar * 2; eighth++) {
    const tick = (bar * beatsPerBar * ticksPerBeat) + (eighth * ticksPerBeat / 2);
    const isOffbeat = eighth % 2 === 1;

    // Open hat on offbeats occasionally
    const isOpen = isOffbeat && (eighth === 3 || eighth === 7) && bar % 2 === 1;

    midiEvents.push({
      id: eventId++,
      type: 'noteOn',
      tick: tick,
      note: isOpen ? drumNotes.openHat : drumNotes.closedHat,
      velocity: isOffbeat ? 70 : 85, // Offbeats softer
      channel: 9,
      duration: ticksPerBeat / 4
    });
  }
}

// Add crash on first beat
midiEvents.push({
  id: eventId++,
  type: 'noteOn',
  tick: 0,
  note: drumNotes.crash,
  velocity: 100,
  channel: 9,
  duration: ticksPerBeat * 2
});

// Sort by tick
midiEvents.sort((a, b) => a.tick - b.tick);

return {
  json: {
    instrument: 'drums',
    bpm: bpm,
    bars: bars,
    events: midiEvents,
    totalTicks: bars * beatsPerBar * ticksPerBeat,
    ticksPerBeat: ticksPerBeat
  }
};

// Convert to MIDI file format
const data = $input.first().json;
const { events, bpm, ticksPerBeat, bars } = data;

// Simple MIDI file structure (Type 0, single track)
const midiData = {
  format: 0,
  tracks: 1,
  ticksPerBeat: ticksPerBeat,
  bpm: bpm,
  track: {
    name: 'House Drums',
    channel: 9, // Drum channel
    events: events.map(e => ({
      type: e.type,
      tick: e.tick,
      note: e.note,
      velocity: e.velocity,
      duration: e.duration
    }))
  }
};

return {
  json: {
    ...data,
    midiData: midiData,
    filename: `house_drums_${bpm}bpm_${bars}bars.mid`
  }
};
